update public.content_prompts set angle = 'Come with me on a 60-second property tour', brief = 'Walk through one current listing. Start with the strongest feature rather than automatically starting at the front door.', say = 'Open with the reason someone should keep watching, then take viewers through 3 to 5 standout features. Finish with the area, price and CTA.', cover = 'Use the strongest property shot with “60-second tour” and the area or property type.', is_video = true, updated_at = now() where kind = 'evergreen' and sort_order = 3;
