update public.content_prompts set angle = 'What an estate agent actually does in a day', brief = 'Capture 4 to 6 honest moments across a normal working day. Include the less polished parts, not just viewings and keys.', say = 'Use timestamps or a short voiceover to explain each moment. Keep it natural and specific to your actual day.', cover = 'Use a candid frame from the day with “A day in estate agency”.', is_video = true, updated_at = now() where kind = 'evergreen' and sort_order = 8;
