update public.content_prompts set angle = 'What is actually happening in your local property market?', brief = 'Give a short local market update using one or two useful data points. Explain what they mean rather than reading out a list of statistics.', say = 'Lead with the most useful takeaway for local sellers or buyers. Give the number, explain the context, then say what you would do with that information.', cover = 'Use the area name plus one headline figure or takeaway. Keep the cover simple.', is_video = true, updated_at = now() where kind = 'evergreen' and sort_order = 12;
